{
  "figure": "W.E.B. Du Bois",
  "primary_sources": [
    {
      "title": "The Souls of Black Folk",
      "url": "https://www.gutenberg.org/files/408/408-h/408-h.htm",
      "why_relevant": "Du Bois's seminal work, offering profound insights into the Black experience in America."
    },
    {
      "title": "The Crisis Magazine Archives",
      "url": "https://babel.hathitrust.org/cgi/mb?a=list;c=111101111;u=1;s=1;r=1;p=1",
      "why_relevant": "Published by the NAACP, it contains Du Bois's essays and commentary on contemporary issues."
    },
    {
      "title": "W.E.B. Du Bois Papers, University of Massachusetts Amherst",
      "url": "https://credo.library.umass.edu/collections/index.php/dubois",
      "why_relevant": "Extensive collection of his personal writings, correspondence, and research materials."
    }
  ],
  "secondary_sources": [
    {
      "title": "W.E.B. Du Bois: A Biography by David Levering Lewis",
      "url": "https://www.hup.harvard.edu/catalog.php?isbn=9780805068122",
      "why_relevant": "A comprehensive and acclaimed biography offering deep analysis of Du Bois's life and work."
    },
    {
      "title": "The W.E.B. Du Bois Center at Harvard University",
      "url": "https://duboiscenter.fas.harvard.edu/",
      "why_relevant": "Provides resources, scholarship, and context for understanding Du Bois's legacy and impact."
    },
    {
      "title": "Stanford Encyclopedia of Philosophy: W.E.B. Du Bois",
      "url": "https://plato.stanford.edu/entries/dubois/",
      "why_relevant": "Scholarly overview of his philosophical contributions and intellectual development."
    }
  ],
  "notes": "Focus on his writings, activism with the NAACP, and intellectual contributions to sociology and civil rights."
}

